const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json.body || item.json;
  const txn = data.transaction || data.tx || data.data || {};

  const rawEventType = String(data.eventType || data.event || data.event_type || data.type || data.action || '').toLowerCase();
  const rawStatus = String(txn.status || data.status || data.state || data.payment_status || '').toLowerCase();
  const memo = String(txn.memo || data.memo || data.description || data.notes || data.title || '').trim();

  let orderId = String(data.order_id || data.orderId || txn.orderId || txn.order_id || '').trim();
  if (!orderId && memo) {
    orderId = memo;
  }
  if (!orderId) {
    orderId = String(txn.id || data.id || txn.externalId || data.reference || '.').trim();
  }

  let amountStr = '.';
  const currency = String(txn.settlementCurrency || data.currency || data.coin || 'USD').toUpperCase();

  if (txn.settlementDisplayAmount !== undefined && txn.settlementDisplayAmount !== null && txn.settlementDisplayAmount !== '') {
    amountStr = String(txn.settlementDisplayAmount).trim();
  } else if (txn.settlementAmount !== undefined && txn.settlementAmount !== null) {
    const rawAmt = Number(txn.settlementAmount);
    if (!isNaN(rawAmt)) {
      amountStr = currency === 'USD' ? (rawAmt / 100).toFixed(2) : String(rawAmt);
    }
  }

  if (amountStr !== '.' && !isNaN(Number(amountStr))) {
    amountStr = Number(amountStr).toFixed(2);
  }

  const customerName = String(data.customer_name || (data.customer && data.customer.name) || data.name || '.').trim();
  const customerEmail = String(data.customer_email || (data.customer && data.customer.email) || data.email || '.').trim();
  const description = memo || String(data.description || data.notes || data.title || '.').trim();

  const isPaid = (
    ['success', 'paid', 'completed', 'settled', 'confirmed'].includes(rawStatus) ||
    (rawEventType.includes('receive') && !['pending', 'failed', 'cancelled', 'failure'].includes(rawStatus)) ||
    ['paid', 'completed', 'settled', 'success', 'confirmed', 'payment.success', 'order.paid', 'invoice.paid'].includes(rawEventType)
  );

  const clientStr = customerName !== '.' ? customerName : (customerEmail !== '.' ? customerEmail : 'Cliente Blink');
  const displayAmount = amountStr !== '.' ? `$${amountStr} ${currency}` : `Monto N/A (${currency})`;

  let telegramText = '';
  let whatsappText = '';

  if (isPaid) {
    telegramText = `🚀 *¡PAGO COMPLETADO EN BLINK!*

💵 *Monto Recibido:* ${displayAmount}
🆔 *Orden ID:* \`${orderId}\`
👤 *Cliente:* ${clientStr}
📋 *Descripción:* ${description}
📊 *Estado:* ✅ Pago Confirmado`;

    whatsappText = `🚀 ¡PAGO COMPLETADO EN BLINK!

💵 Monto Recibido: ${displayAmount}
🆔 Orden ID: ${orderId}
👤 Cliente: ${clientStr}
📋 Descripción: ${description}
📊 Estado: ✅ Pago Confirmado`;
  } else {
    telegramText = `🛒 *¡NUEVA ORDEN CREADA EN BLINK!*

💵 *Monto:* ${displayAmount}
🆔 *Orden ID:* \`${orderId}\`
👤 *Cliente:* ${clientStr}
📋 *Descripción:* ${description}
📊 *Estado:* 🟡 Orden Creada / Pendiente de Pago`;

    whatsappText = `🛒 ¡NUEVA ORDEN CREADA EN BLINK!

💵 Monto: ${displayAmount}
🆔 Orden ID: ${orderId}
👤 Cliente: ${clientStr}
📋 Descripción: ${description}
📊 Estado: 🟡 Orden Creada / Pendiente`;
  }

  results.push({
    json: {
      ...data,
      isPaid,
      order_id: orderId,
      amount: amountStr,
      currency,
      displayAmount,
      telegramText,
      whatsappText,
      clientStr,
      description
    }
  });
}

return results;
